ALTER TABLE "order_status_events" ADD CONSTRAINT "order_status_events_transition_valid" CHECK (("order_status_events"."from_status" IS NULL AND "order_status_events"."to_status" = 'received') OR ("order_status_events"."from_status" IN ('received', 'approved', 'rejected', 'preparing', 'ready', 'delivering', 'completed') AND "order_status_events"."to_status" IN ('received', 'approved', 'rejected', 'preparing', 'ready', 'delivering', 'completed') AND "order_status_events"."from_status" <> "order_status_events"."to_status"));